const number=n=>new Intl.NumberFormat('ru-RU').format(n);
const ageText=e=>e.sourceProvider==='Tripster'?'Детская программа':e.ageRestriction==null?'Возраст уточняется':e.ageRestriction+'+';
const basePriceText=e=>e.priceData.free_confirmed?'Бесплатно':e.priceData.min==null?(e.priceData.max==null?'Цена уточняется':'до '+number(e.priceData.max)+' ₽'):(e.priceData.min===e.priceData.max?'':'от ')+number(e.priceData.min)+' ₽';
const priceText=e=>basePriceText(e)+(e.priceData.unit?' '+e.priceData.unit:'');
const dateText=e=>{if(e.dates.length){const [from,to]=selectedDateRange();const d=e.dates.find(d=>(!from||d.date>=from)&&(!to||d.date<=to))||e.dates[0];return shortDate(d.date)+' · '+d.time;}const s=e.schedule;if(s.mode==='appointment')return 'По записи · дата у гида';if(s.mode==='until')return 'Даты и график у площадки';if(s.mode==='between'&&s.primaryDate&&s.secondaryDate)return 'Несколько дат · расписание у площадки';if(s.primaryDate)return new Date(s.primaryDate).toLocaleDateString('ru-RU',{day:'numeric',month:'long',timeZone:'Europe/Moscow'})+' · время уточняется';return 'Даты уточняются у площадки'};
const sourceName=e=>e.sourceProvider==='Tripster'?'Tripster':e.sources[0].url.includes('culture.ru')?'Культура.РФ':'Афиша.ру';
const isWeekend=e=>e.dates.some(d=>['2026-10-31','2026-11-01'].includes(d.date));
const isScience=e=>/космо|планетар|наук|физик|хими|робот|опыт|технолог/i.test(e.title);
const heroIds=['ps-abaa7073555a5b88a4','ps-ac70ad91008575ab79','ps-296b00ce1e32f262f9'];

const defaults={page:'home',city:'Москва',date:'all',age:'all',types:[],free:false,family:false,district:'all',query:'',sort:'date',layout:'grid',saved:[],favorites:false,event:"ps-abaa7073555a5b88a4",tab:'description',slot:'12:00'};
Object.assign(defaults,{slide:0,gallery:0,heroRevision:2,metro:'all',venue:'all',homeQuick:'all'});let state={...defaults};const settings={radius:18,coverHeight:190,view:'С фотографиями'};const $=s=>root.querySelector(s);const $$=s=>[...root.querySelectorAll(s)];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<i data-lucide="${n}" class="ps-lucide" aria-hidden="true"></i>`;
const money=p=>p?new Intl.NumberFormat('ru-RU').format(p)+' ₽':'Бесплатно';
const shortDate=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
const longDate=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});
const plural=(n,a,b,c)=>n%10===1&&n%100!==11?a:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?b:c;
function icons(){if(globalThis.lucide)globalThis.lucide.createIcons({attrs:{width:17,height:17}})}
function hydrate(scope=root){scope.querySelectorAll('[data-asset]').forEach(i=>{const k=i.dataset.asset;if(assets[k])i.src=assets[k]})}
function save(){const api=window.openai;if(api?.setWidgetState)api.setWidgetState({modelContent:{screen:state.page,city:state.city,event:state.event,filters:{age:state.age,type:state.types,date:state.date,free:state.free},design:settings,slide:state.slide},privateContent:{state}}).catch(()=>{})}
function note(message){$('#ps-review-status').hidden=false;$('#ps-review-status').textContent=message}
function current(){return items.find(x=>x.id===state.event)||items[0]}
function card(e){const saved=state.saved.includes(e.id);return `<article class="ps-event-card"><button class="ps-card-cover" data-event="${e.id}" aria-label="${esc(e.title)}">${e.media.length?`<img src="${esc(e.media[0].url)}" alt="${esc(e.title)} — изображение мероприятия" loading="lazy" decoding="async" referrerpolicy="no-referrer">`:`<div class="ps-no-poster"><span>${esc(e.type)}</span><strong>Афиша пока не опубликована</strong></div>`}<span class="ps-age-tag">${ageText(e)}</span></button><button class="ps-heart" data-save="${e.id}" aria-label="Сохранить событие" aria-pressed="${saved}">${icon('heart')}</button><div class="ps-card-content"><div class="ps-event-date">${esc(dateText(e))}</div><h3><button class="ps-title-button" data-event="${e.id}">${esc(e.title)}</button></h3><div class="ps-event-location">${icon('map-pin')}<span>${esc(e.place)}<br>Москва${e.district?' · '+esc(e.district):''}</span></div><div class="ps-card-bottom"><div><span class="ps-price ${e.priceData.free_confirmed?'free':''}">${esc(priceText(e))}</span><br><small>${esc(e.type)}</small></div><button class="ps-open-card" data-event="${e.id}" aria-label="Подробнее">${icon('arrow-up-right')}</button></div></div></article>`}

function filtered(){let a=items.filter(e=>!state.favorites||state.saved.includes(e.id));if(state.date==='weekend')a=a.filter(isWeekend);if(state.date==='tomorrow')a=a.filter(e=>e.dates.some(d=>d.date==='2026-11-01'));if(state.age!=='all'){const [lo]=state.age.split('-').map(Number);a=a.filter(e=>e.ageRestriction!=null&&e.ageRestriction<=lo)}if(state.types.length)a=a.filter(e=>state.types.some(t=>(e.categories||[e.type]).includes(t)));if(state.free)a=a.filter(e=>e.priceData.free_confirmed);if(state.district!=='all')a=a.filter(e=>e.district===state.district);if(state.venue!=='all')a=a.filter(e=>e.place===state.venue);if(state.query){const q=state.query.toLowerCase();a=a.filter(e=>(e.title+' '+e.place+' '+e.type+' '+e.address).toLowerCase().includes(q))}a.sort((a,b)=>state.sort==='price'||state.sort==='free'?(a.price??Infinity)-(b.price??Infinity):(a.date||'9999').localeCompare(b.date||'9999')||a.time.localeCompare(b.time));return a}

function updateChrome(){root.querySelectorAll('.city-name,[data-city-label]').forEach(e=>e.textContent=state.city);$('#ps-favorites-count').textContent=state.saved.length;$$('[data-screen]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.screen===state.page)));$('#ps-city-options').innerHTML=['Вся Россия',...cities].map(c=>`<button type="button" data-city="${c}" aria-pressed="${c===state.city}">${c}</button>`).join('')}
function syncFilters(){syncLocations(); $('#ps-age').value=state.age;$('#ps-free').checked=state.free;$('#ps-family').checked=state.family;$('#ps-district').value=state.district;$('#ps-query').value=state.query;$('#ps-sort').value=state.sort;$$('[data-type]').forEach(e=>e.checked=state.types.includes(e.dataset.type));$$('[data-date]').forEach(e=>e.setAttribute('aria-pressed',String(state.date===e.dataset.date)));$$('[data-layout]').forEach(e=>e.setAttribute('aria-pressed',String(state.layout===e.dataset.layout)));$('#ps-hero-age').value=state.age;$('#ps-hero-date').value=state.date;}
