let mapZoom=1,swipeStart=null,suppressPosterClick=0;
function posterSlides(){return heroIds.map(id=>items.find(e=>e.id===id)).filter(Boolean).map(e=>({event:e,image:assets[e.image+'-banner']?e.image+'-banner':e.image,title:esc(e.title.replace(/^Мастер-класс\s*[«"]?/,'').replace(/[»"]$/,''))}))}

function renderPoster(announce=false){let slides=posterSlides();state.slide=((Number(state.slide)||0)%slides.length+slides.length)%slides.length;const s=slides[state.slide],e=s.event;$('#ps-poster-image').src=e.media[0]?.url||'';$('#ps-poster-image').alt=e.title+' — изображение мероприятия';$('#ps-poster-title').innerHTML=s.title;$('#ps-poster-kicker').textContent=e.type+' · Москва';$('#ps-poster-meta').textContent=dateText(e)+' · '+ageText(e)+' · '+priceText(e);$('#ps-poster-link').dataset.heroOpen=e.id;$('#ps-poster-link').href='#'+e.id;$('#ps-poster-link').setAttribute('aria-label',e.title);$('#ps-poster-dots').innerHTML=slides.map((s,i)=>`<button data-poster-index="${i}" aria-label="Афиша ${i+1}" aria-pressed="${i===state.slide}"></button>`).join('');$('#ps-poster-counter').textContent=String(state.slide+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');if(announce)$('#ps-poster-announcement').textContent=e.title;icons()}

function movePoster(delta){state.slide=(Number(state.slide)||0)+delta;renderPoster(true);save()}
function galleryImages(){return current().media.map(m=>({url:m.url,label:'Изображение мероприятия',credit:m.credit,source:m.source_url}));}

function renderGallery(){const a=galleryImages();if(!a.length){$('#ps-detail-photo').hidden=true;$('#ps-gallery-counter').textContent='Афиша пока не опубликована';$('#ps-gallery-thumbs').innerHTML='';return}$('#ps-detail-photo').hidden=false;state.gallery=((Number(state.gallery)||0)%a.length+a.length)%a.length;const g=a[state.gallery];$('#ps-detail-photo').src=g.url;$('#ps-detail-photo').alt=current().title;$('#ps-detail-photo').referrerPolicy='no-referrer';$('#ps-detail-photo').style.transform='none';$('#ps-detail-photo').style.objectFit='contain';$('#ps-gallery-counter').textContent=(state.gallery+1)+' / '+a.length;$('#ps-gallery-thumbs').innerHTML=a.length>1?a.map((m,i)=>`<button data-gallery-index="${i}" aria-label="Изображение ${i+1}" aria-pressed="${state.gallery===i}"><img src="${esc(m.url)}" alt="Изображение мероприятия" referrerpolicy="no-referrer"></button>`).join(''):'';$$('[data-gallery-step]').forEach(b=>{b.hidden=a.length<2});let c=$('#ps-media-credit');if(!c){c=document.createElement('p');c.id='ps-media-credit';c.className='ps-media-credit';$('#ps-gallery-thumbs').after(c)}c.innerHTML=`Изображение: ${esc(g.credit)} · <a href="${esc(current().sources[0].url)}" target="_blank" rel="noopener">Источник</a>`;}

function syncLocations(){const options=(values,selected,label)=>`<option value="all">${label}</option>`+[...new Set(values)].filter(Boolean).sort().map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');$('#ps-district').innerHTML=options(items.map(e=>e.district),state.district,'Все округа и территории');$('#ps-venue').innerHTML=options(items.map(e=>e.place),state.venue,'Любая площадка');$('#ps-metro').innerHTML='<option value="all">Станции пока уточняются</option>';$('#ps-metro').disabled=true;$('#ps-family').disabled=true;$('#ps-family').closest('label').hidden=true;}

function drawVenueMap(){const container=$('#ps-location-map');if(state.page!=='detail')return;const e=current();if(container.dataset.event===e.id&&container.querySelector('iframe'))return;container.dataset.event=e.id;const point=e.coordinates;const src=point?'https://yandex.ru/map-widget/v1/?ll='+encodeURIComponent(point.join(','))+'&z=16&pt='+encodeURIComponent(point.join(',')+',pm2rdm')+'&lang=ru_RU':'https://yandex.ru/map-widget/v1/?text='+encodeURIComponent('Москва '+e.address+' '+e.place)+'&z=16&lang=ru_RU';container.innerHTML=`<iframe title="Яндекс Карты: ${esc(e.place)}" src="${esc(src)}" loading="lazy" allowfullscreen referrerpolicy="no-referrer-when-downgrade"></iframe>`;}

function renderLocation(){const e=current();$('#ps-location-name').textContent=e.place;$('#ps-location-address').textContent=e.address;$('#ps-location-metro').textContent=e.coordinates?'Место проведения на Яндекс Картах':'Точные координаты площадки уточняются';drawVenueMap();}

function renderDiscovery(){$('#ps-discovery-title').textContent='Афиша Москвы по категориям';$('#ps-discovery-links').innerHTML=categories.map(([cat])=>`<a href="#catalog" data-category="${esc(cat)}">${esc(cat)} · ${items.filter(e=>(e.categories||[e.type]).includes(cat)).length}</a>`).join('');}

$('#ps-poster').addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();movePoster(e.key==='ArrowRight'?1:-1)}});
$('#ps-poster').addEventListener('pointerdown',e=>{if(e.target.closest('[data-poster-step],[data-poster-index]'))return;swipeStart={x:e.clientX,y:e.clientY}});
$('#ps-poster').addEventListener('pointerup',e=>{if(!swipeStart)return;let dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.2){suppressPosterClick=Date.now()+400;movePoster(dx<0?1:-1)}});
$('#ps-gallery').addEventListener('pointerdown',e=>{swipeStart={x:e.clientX,y:e.clientY,gallery:true}});
$('#ps-gallery').addEventListener('pointerup',e=>{if(!swipeStart?.gallery)return;let dx=e.clientX-swipeStart.x;swipeStart=null;if(Math.abs(dx)>45){state.gallery=(Number(state.gallery)||0)+(dx<0?1:-1);renderGallery();save()}});
new ResizeObserver(()=>{if(state.page==='detail')drawVenueMap()}).observe($('#ps-location-map'));

function renderHome(){let a=items.filter(e=>e.dates.length).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));if(state.homeQuick==='free')a=a.filter(e=>e.priceData.free_confirmed);if(state.homeQuick==='teens')a=a.filter(e=>e.ageRestriction!=null&&e.ageRestriction<=13);if(state.homeQuick==='science')a=a.filter(isScience);if(state.homeQuick==='creative')a=a.filter(e=>e.type==='Мастер-классы');let pick=[];if(state.homeQuick==='all'){const cats=['Мастер-классы','Спектакли','Экскурсии','Концерты','Цирк и шоу'];for(const t of cats){const x=a.find(e=>e.type===t);if(x)pick.push(x)}for(const e of a){if(pick.length>=6)break;if(!pick.includes(e))pick.push(e)}}else pick=a.slice(0,6);$('#ps-home-events').innerHTML=pick.map(card).join('')||'<p>Для этого фильтра подтверждённые даты пока не найдены. Посмотрите всю афишу.</p>';$$('[data-home-quick]').forEach(b=>b.setAttribute('aria-pressed',String(state.homeQuick===b.dataset.homeQuick)));renderPoster();$('#ps-cities').innerHTML=`<button class="ps-city-chip" data-city-catalog="Москва">Москва<small>${number(items.length)} событий ↗</small></button>`;}

function renderCatalog(){$('#ps-catalog-heading').textContent=state.favorites?'Сохранённые события':'Куда сходить с ребёнком в Москве';const a=filtered();const size=24,total=Math.ceil(a.length/size);state.catalogPage=Math.min(state.catalogPage||0,Math.max(0,total-1));$('#ps-results-count').textContent=number(a.length)+' '+plural(a.length,'событие','события','событий');$('#ps-catalog-grid').innerHTML=a.slice(state.catalogPage*size,(state.catalogPage+1)*size).map(card).join('');$('#ps-empty').hidden=a.length>0;$('#ps-catalog-grid').classList.toggle('ps-list-view',state.layout==='list');let tags=[];if(state.rangeFrom||state.date!=='all')tags.push(['dates',dateButtonText()]);if(state.age!=='all')tags.push(['age',state.age.replace('-','–')+' лет']);state.types.forEach(t=>tags.push(['type:'+t,t]));if(state.free)tags.push(['free','Бесплатно']);if(state.district!=='all')tags.push(['district',state.district]);if(state.venue!=='all')tags.push(['venue',state.venue]);if(state.favorites)tags.push(['favorites','Сохранённое']);$('#ps-active-filters').innerHTML=tags.map(([key,label])=>`<button data-remove="${key}" aria-label="Убрать фильтр: ${esc(label)}">${esc(label)} ×</button>`).join('');$('#ps-mobile-filter-count').textContent=tags.length?'· '+tags.length:'';const indexes=[...new Set([0,state.catalogPage-1,state.catalogPage,state.catalogPage+1,total-1])].filter(i=>i>=0&&i<total).sort((a,b)=>a-b);$('#ps-live-pagination').innerHTML=indexes.map((i,n)=>`${n&&i>indexes[n-1]+1?'<span>…</span>':''}<button data-page-number="${i}" aria-current="${i===state.catalogPage?'page':'false'}">${i+1}</button>`).join('')+`<span>По 24 события · ${number(a.length)} всего</span>`;syncFilters();renderDiscovery();}

function detailPane(){const e=current();$('#ps-detail-pane').setAttribute('aria-labelledby','ps-tab-'+state.tab);$$('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===state.tab)));if(state.tab==='description')$('#ps-detail-pane').innerHTML=`<h2>О мероприятии</h2><p>«${esc(e.title)}» — ${esc(e.type.toLowerCase())} на площадке «${esc(e.place)}» в Москве.</p><p>${esc(dateText(e))}. Возрастной ценз: ${ageText(e)}. ${esc(priceText(e))}.</p><p>Подробная программа и условия посещения опубликованы в карточке площадки.</p><a class="ps-secondary" href="${esc(e.sources[0].url)}" target="_blank" rel="noopener">Открыть полное описание ${icon('arrow-up-right')}</a>`;if(state.tab==='program')$('#ps-detail-pane').innerHTML=`<h2>Даты и программа</h2>${e.dates.length?e.dates.map(d=>`<div class="ps-program"><b>${d.time}</b><div><strong>${longDate(d.date)}</strong><p>Сеанс указан в опубликованной афише.</p></div></div>`).join(''):`<p>${esc(dateText(e))}. Точное расписание посещения уточните на сайте площадки.</p>`}<a class="ps-secondary" href="${esc(e.sources[0].url)}" target="_blank" rel="noopener">Программа у источника ↗</a>`;if(state.tab==='place')$('#ps-detail-pane').innerHTML=`<h2>${esc(e.place)}</h2><p>${esc(e.address)}</p><p>Правила входа, сопровождения детей и доступность площадки уточните до посещения.</p>`;}

function renderDetail(){const e=current();$('#ps-detail-title').textContent=e.title;$('#ps-detail-type').textContent=e.type;$('#ps-detail-eyebrow').textContent='Москва · '+e.type;$('#ps-detail-meta').innerHTML=`<span>${ageText(e)}</span><span>Москва</span><span>${esc(e.type)}</span>`;$('#ps-organizer-name').textContent=e.place;$('#ps-booking').innerHTML=`<small>Стоимость по опубликованной афише</small><div class="ps-booking-price">${esc(priceText(e))}</div><div class="ps-info-line">${icon('calendar-days')}<div><strong>${esc(dateText(e))}</strong><span>Время московское</span></div></div><div class="ps-info-line">${icon('map-pin')}<div><strong>${esc(e.place)}</strong><span>${esc(e.address)}</span></div></div>${e.dates.length?`<p class="ps-upcoming">Опубликованные сеансы</p><div class="ps-times">${e.dates.slice(0,6).map(d=>`<button data-slot="${d.time}" aria-pressed="${state.slot===d.time}">${shortDate(d.date)} · ${d.time}</button>`).join('')}</div>`:''}<button class="ps-main-button" data-action="organizer">Билеты и условия ${icon('arrow-up-right')}</button><button class="ps-text-button ps-save-detail" data-save="${e.id}">${icon('heart')}${state.saved.includes(e.id)?'Событие сохранено':'Сохранить на потом'}</button><p class="ps-booking-note">Окончательную цену и наличие мест проверьте у площадки. Источник: ${sourceName(e)}.</p>`;detailPane();$('#ps-related').innerHTML=items.filter(x=>x.id!==e.id&&x.type===e.type).slice(0,3).map(card).join('');renderGallery();renderLocation();}

function render(){['home','catalog','detail'].forEach(p=>$('#ps-'+p).hidden=state.page!==p);updateChrome();renderHome();renderCatalog();renderDetail();hydrate();icons()}
function go(page,event){if(event){state.event=event;state.slot=current().slots[0];state.tab='description';state.gallery=0}state.page=page;$('#ps-city-picker').hidden=true;render();save();$('#ps-site-viewport').scrollTop=0;root.scrollIntoView({block:'start'})}
function reset(){Object.assign(state,{date:'all',age:'all',types:[],free:false,family:false,district:'all',query:'',favorites:false,metro:'all',venue:'all'});render();save()}
$('#ps-categories').hidden=true;$('#ps-categories').innerHTML=categories.map(([t,i,sub])=>`<button type="button" class="ps-category" data-category="${t}">${icon(i)}<span><strong>${t}</strong><small>${sub}</small></span></button>`).join('');$('#ps-type-filters').innerHTML=categories.map(([t])=>`<label class="ps-check"><input type="checkbox" data-type="${t}">${t}</label>`).join('');
root.addEventListener('click',e=>{let b=e.target.closest('button,a');if(!b||!root.contains(b))return;if(b.dataset.heroOpen){e.preventDefault();if(Date.now()<suppressPosterClick)return;const ev=items.find(x=>x.id===b.dataset.heroOpen);state.city=ev.city;go('detail',ev.id);return}if(b.dataset.posterStep){movePoster(Number(b.dataset.posterStep));return}if(b.dataset.posterIndex!==undefined){state.slide=Number(b.dataset.posterIndex);renderPoster(true);save();return}if(b.dataset.galleryStep){state.gallery=(Number(state.gallery)||0)+Number(b.dataset.galleryStep);renderGallery();save();return}if(b.dataset.galleryIndex!==undefined){state.gallery=Number(b.dataset.galleryIndex);renderGallery();save();return}if(b.dataset.mapZoom){mapZoom=Math.max(.65,Math.min(2,mapZoom+Number(b.dataset.mapZoom)*.25));drawVenueMap();return}if(b.dataset.pageNumber!==undefined){state.catalogPage=Number(b.dataset.pageNumber);renderCatalog();icons();$('#ps-site-viewport').scrollTop=160;return}if(b.dataset.homeQuick){state.homeQuick=b.dataset.homeQuick;renderHome();icons();save();return}if(b.dataset.discovery){e.preventDefault();const key=b.dataset.discovery;if(key==='weekend')state.date='weekend';if(key==='free')state.free=true;if(key==='teens')state.age='13-17';if(key==='science')state.types=['Мастер-классы'];if(key==='metro')state.metro='Сокол';if(key==='district')state.district='Сокол';if(key==='venue')state.venue='Научная мастерская';renderCatalog();icons();save();$('#ps-site-viewport').scrollTop=140;return}if(b.dataset.screen){if(b.dataset.screen==='catalog')state.favorites=false;if(b.dataset.screen==='detail'&&current().city!==state.city&&state.city!=='Вся Россия'){state.event=(items.find(x=>x.city===state.city)||items[0]).id;state.slot=current().slots[0]}go(b.dataset.screen);return}if(b.dataset.event){go('detail',b.dataset.event);return}if(b.dataset.save){const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];render();save();return}if(b.dataset.city){state.city=b.dataset.city;state.district='all';state.metro='all';state.venue='all';state.slide=0;if(state.page==='detail')state.page='catalog';$('#ps-city-picker').hidden=true;render();save();return}if(b.dataset.cityCatalog){state.city=b.dataset.cityCatalog;state.district='all';state.metro='all';state.venue='all';state.slide=0;state.favorites=false;go('catalog');return}if(b.dataset.category){state.types=[b.dataset.category];state.favorites=false;go('catalog');return}if(b.dataset.date){state.date=b.dataset.date;renderCatalog();icons();save();return}if(b.dataset.layout){state.layout=b.dataset.layout;renderCatalog();icons();save();return}if(b.dataset.tab){state.tab=b.dataset.tab;detailPane();save();return}if(b.dataset.slot){state.slot=b.dataset.slot;renderDetail();icons();save();return}if(b.dataset.remove){const k=b.dataset.remove;if(k.startsWith('type:'))state.types=state.types.filter(t=>t!==k.slice(5));else if(['age','district','metro','venue'].includes(k))state[k]='all';else state[k]=false;renderCatalog();icons();save();return}const action=b.dataset.action;if(action==='home')go('home');if(action==='catalog'){state.favorites=false;go('catalog')}if(action==='city'||b.hasAttribute('data-city-open')){$('#ps-city-picker').hidden=!$('#ps-city-picker').hidden}if(action==='close-city')$('#ps-city-picker').hidden=true;if(action==='reset')reset();if(action==='favorites'){state.favorites=true;state.date='all';go('catalog')}if(action==='organizer')window.open(current().sources[0].url,'_blank','noopener');if(action==='route')window.open('https://yandex.ru/maps/?text='+encodeURIComponent('Москва '+current().address),'_blank','noopener');if(action==='home-activities')window.open('https://pro-schools.ru/blog/poprobuj-novoe-za-vyhodnye/','_blank','noopener');if(b.id==='ps-mobile-filter'){const f=$('#ps-filters');f.classList.toggle('open');b.setAttribute('aria-expanded',String(f.classList.contains('open')))}if(b.closest('.ps-chrome')&&b.tagName==='A'){e.preventDefault();if(b.classList.contains('logo')||b.getAttribute('href')==='/afisha/'){const dialog=$('#mobile-nav');if(dialog){dialog.removeAttribute('open');dialog.style.display='none'}go('home');}else note('Раздел «'+b.innerText.trim().replace(/↗/g,'')+'» уже существует на ProSchools. В макете остаёмся в афише.')}if(b.classList.contains('drop-trigger')||b.classList.contains('exam-trigger')){const id=b.getAttribute('aria-controls');const panel=$('#'+id);if(panel){const open=panel.hidden;$$('.mega').forEach(p=>p.hidden=true);panel.hidden=!open;b.setAttribute('aria-expanded',String(open))}}if(b.classList.contains('close-panel'))$$('.mega').forEach(p=>p.hidden=true);if(b.hasAttribute('data-search-open')){go('catalog');$('#ps-query').focus()}if(b.classList.contains('mobile-toggle')){const dialog=$('#mobile-nav');if(dialog){dialog.setAttribute('open','');dialog.style.display='block'}}if(b.hasAttribute('data-close-mobile')){const dialog=$('#mobile-nav');dialog.removeAttribute('open');dialog.style.display='none'}});
root.addEventListener('change',e=>{const t=e.target;if(t.id==='ps-age')state.age=t.value;if(t.id==='ps-free')state.free=t.checked;if(t.id==='ps-family')state.family=t.checked;if(t.id==='ps-district')state.district=t.value;if(t.id==='ps-sort')state.sort=t.value;if(t.id==='ps-metro')state.metro=t.value;if(t.id==='ps-venue')state.venue=t.value;if(t.dataset.type){state.types=t.checked?[...new Set([...state.types,t.dataset.type])]:state.types.filter(x=>x!==t.dataset.type)}if(t.closest('#ps-filters')||t.id==='ps-sort'){state.catalogPage=0;renderCatalog();icons();save()}});
$('#ps-query').addEventListener('input',e=>{state.query=e.target.value;state.catalogPage=0;renderCatalog();icons();save()});$('#ps-search-form').addEventListener('submit',e=>e.preventDefault());$('#ps-hero-search').addEventListener('submit',e=>{e.preventDefault();state.date=$('#ps-hero-date').value;state.age=$('#ps-hero-age').value;state.favorites=false;go('catalog')});
function restore(x){return;const stored=x.privateContent?.state;if(stored){state={...defaults,...stored};if(stored.heroRevision!==2){state.page='home';state.slide=0;state.heroRevision=2;}if(!['home','catalog','detail'].includes(state.page))state.page='home';if(!Array.isArray(state.saved))state.saved=[];if(!Array.isArray(state.types))state.types=[];render()}}
const categorySlugs={'Спектакли':'spektakli','Мастер-классы':'master-klassy','Выставки и музеи':'vystavki','Экскурсии':'ekskursii','Концерты':'kontserty','Занятия и обучение':'zanyatiya','Встречи и программы':'programmy','Кино':'kino','Квесты и игры':'kvesty','Цирк и шоу':'tsirk','Спорт':'sport','Праздники и фестивали':'prazdniki'};
const categoryHeadings={'Спектакли':'Спектакли для детей в Москве','Мастер-классы':'Мастер-классы для детей в Москве','Выставки и музеи':'Выставки и музеи для детей в Москве','Экскурсии':'Экскурсии для детей в Москве','Концерты':'Концерты для детей в Москве','Занятия и обучение':'Занятия для детей в Москве','Встречи и программы':'Познавательные программы для детей в Москве','Кино':'Кино для детей в Москве','Квесты и игры':'Квесты и игры для детей в Москве','Цирк и шоу':'Цирк и шоу для детей в Москве','Спорт':'Спортивные события для детей в Москве','Праздники и фестивали':'Праздники и фестивали для детей в Москве'};
const categoryCopy={
'Концерты':['Как выбрать концерт для ребёнка','Сравните музыкальный формат: вокальная программа, инструментальный концерт или музыкальная история требуют разного внимания. Для первого посещения заранее уточните продолжительность, громкость и возможность выйти из зала. Ценз 0+ или 6+ показывает ограничение на вход, а рекомендуемый возраст лучше уточнить у площадки.','Нужен ли ребёнку отдельный билет?','Условия зависят от площадки и программы. Проверьте, нужен ли отдельный билет ребёнку и взрослому, есть ли места для семей и можно ли войти после начала.'],
'Спектакли':['Как выбрать детский спектакль','Для первого знакомства с театром сравните кукольные постановки, музыкальные сказки и драматические спектакли. Уточните длительность, наличие антракта и рассадку. Не все постановки с одинаковым возрастным цензом рассчитаны на одинаковый уровень внимания.','На что обратить внимание перед походом в театр?','Проверьте точную сцену, начало показа и правила сопровождения. Один театр может проводить спектакли на нескольких площадках; ориентируйтесь на адрес конкретного события.'],
'Мастер-классы':['Как выбрать мастер-класс для ребёнка','Выбирайте занятие по тому, что ребёнок хочет попробовать: рисование, керамику, создание мультфильма или работу с материалами. До записи уточните, входят ли материалы в стоимость и можно ли забрать результат сразу. Для керамики отдельно проверьте условия обжига.','Нужна ли предварительная подготовка?','Это зависит от программы. Проверьте требования к навыкам, одежде и сопровождению; возрастной ценз сам по себе не означает, что занятие подходит начинающим.'],
'Выставки и музеи':['Как спланировать поход в музей с ребёнком','Сравните самостоятельное посещение и программу с экскурсоводом. У постоянных экспозиций проверьте часы работы, санитарные дни и необходимость выбрать сеанс. Для временной выставки учитывайте дату окончания и ограничения на посещение отдельных залов.','Можно ли прийти в любое время?','Не всегда: вход может быть по сеансам, а экскурсии — по предварительной записи. График музея и расписание конкретной программы могут различаться.'],
'Экскурсии':['Как выбрать экскурсию для семьи','Проверьте место встречи, длину маршрута и формат: прогулка по городу, музейная экскурсия или транспортная программа. Для уличных маршрутов учитывайте погоду и возможность остановиться на отдых.','Где встречаться с экскурсоводом?','Место встречи может отличаться от адреса музея или основной площадки. Откройте карточку организатора и проверьте вход, время сбора и контакты перед выходом.'],
'Кино':['Как выбрать киносеанс для ребёнка','Сравните возрастной ценз, продолжительность и формат показа. Для первого посещения кинотеатра учитывайте громкость и темноту в зале. Проверьте, указан ли сеанс с субтитрами или специальными условиями.','Где уточнить актуальное расписание?','Откройте источник выбранного события: кинотеатр может менять сеансы, залы и доступные места. Цена в афише относится к опубликованному предложению.'],
'Квесты и игры':['Как выбрать квест для детей','Уточните сложность, длительность, размер команды и участие ведущего. Для сюжетных квестов проверьте, есть ли пугающие сцены и может ли взрослый проходить маршрут вместе с ребёнком.','Нужен ли сопровождающий?','Правила зависят от возраста и формата. Спросите у площадки о сопровождении, роли ведущего и том, включена ли оплата взрослого в стоимость команды.'],
'Цирк и шоу':['Как выбрать цирковое представление','Сравните формат шоу, длительность, расположение мест и наличие антракта. Для маленьких детей заранее уточните громкие эффекты, затемнение и ограничения на проход в зал.','На что влияет выбранное место?','Обзор, близость к арене и итоговая цена зависят от сектора. Проверьте схему зала и точный адрес: гастрольная программа может идти на разных площадках.'],
'Занятия и обучение':['Как выбрать пробное занятие','Сравните тему, формат группы, длительность и требования к подготовке. Уточните, является ли предложение разовым занятием или частью курса и входит ли необходимое оборудование в стоимость.','Пробное занятие обязывает покупать курс?','Проверьте условия у организатора. В афише показано опубликованное предложение; договор, дальнейшая оплата и правила отказа зависят от школы или площадки.'],
'Встречи и программы':['Как выбрать познавательную программу','Ориентируйтесь на тему и формат участия: беседа, чтение, интерактивная встреча или музейная программа. Уточните, предполагается ли активное участие детей и сколько длится встреча.','Нужна ли предварительная запись?','Даже на бесплатные встречи может требоваться регистрация. Проверьте наличие мест и правила сопровождения в исходной карточке.'],
'Спорт':['Как выбрать спортивное событие для семьи','Проверьте формат: зрительское мероприятие или активное участие. Для участия уточните требования к форме и подготовке; для посещения — сектор, ограничения на вход и правила сопровождения.','Что проверить перед посещением?','Точный адрес, время открытия входа, требования к документам и список разрешённых вещей. У разных спортивных площадок условия могут отличаться.'],
'Праздники и фестивали':['Как выбрать семейный праздник','Проверьте место проведения, время работы зон и правила входа. Для фестиваля на улице заранее посмотрите прогноз погоды и уточните, какие активности входят в билет.','Включены ли все развлечения в билет?','Не обязательно: отдельные мастер-классы, аттракционы или питание могут оплачиваться дополнительно. Сверьте состав программы у организатора.']};
const todayISO=new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Moscow'});
const addDay=(iso,n)=>{const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+n);return d.toLocaleDateString('sv-SE')};
const isoLabel=iso=>new Date(iso+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
let nearPoint=null,nearLabel='',pickMapPoint=false,catalogMap=null,detailMap=null,mapMarkers=[],openPopup=null,popupAnchor=null,routeKey='';
Object.assign(state,{rangeFrom:null,rangeTo:null,okrug:'all',nearRadius:3,metroRadius:1.5});
const initialCat=Object.keys(categorySlugs).find(c=>location.pathname.split('/').filter(Boolean).includes(categorySlugs[c]));
if(initialCat){state.types=[initialCat];state.page='catalog'}
if(location.hash==='#catalog'||new URLSearchParams(location.search).get('view')==='catalog')state.page='catalog';
function haversine(a,b){const r=Math.PI/180,p1=a[1]*r,p2=b[1]*r,dp=(b[1]-a[1])*r,dl=(b[0]-a[0])*r;return 6371*2*Math.atan2(Math.sqrt(Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2),Math.sqrt(1-(Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2)))}
function dateMatches(e){let from=state.rangeFrom,to=state.rangeTo||from;if(!from){if(state.date==='tomorrow')from=to=addDay(todayISO,1);if(state.date==='today')from=to=todayISO;if(state.date==='weekend'){const day=new Date(todayISO+'T12:00:00').getDay();from=addDay(todayISO,(6-day+7)%7);to=addDay(from,1)}}if(!from)return true;if(e.dates.some(d=>d.date>=from&&d.date<=to))return true;if(e.type==='Выставки и музеи'&&e.schedule.mode==='until'){const end=(e.schedule.primaryDate||'').slice(0,10);return end>=from}return false}
const baseFilter=filtered;
filtered=function(){const date=state.date;state.date='all';let a=baseFilter();state.date=date;a=a.filter(dateMatches);if(state.okrug!=='all')a=a.filter(e=>e.okrug===state.okrug);if(state.metro!=='all'){const station=geography.stations.find(s=>s.id===state.metro);a=a.filter(e=>station&&e.coordinates&&haversine(e.coordinates,[station.lng,station.lat])<=state.metroRadius)}if(nearPoint)a=a.filter(e=>e.coordinates&&haversine(e.coordinates,nearPoint)<=Number(state.nearRadius));if(nearPoint&&state.sort==='distance')a.sort((a,b)=>haversine(a.coordinates,nearPoint)-haversine(b.coordinates,nearPoint));return a};
function closePopup(){if(openPopup)openPopup.remove();if(popupAnchor)popupAnchor.setAttribute('aria-expanded','false');openPopup=null;popupAnchor=null}
function placePopup(panel,anchor){closePopup();openPopup=panel;popupAnchor=anchor;root.appendChild(panel);anchor.setAttribute('aria-expanded','true');const r=anchor.getBoundingClientRect(),w=Math.min(panel.classList.contains('ps-calendar')?650:370,innerWidth-24);panel.style.width=w+'px';panel.style.left=Math.max(12,Math.min(r.left,innerWidth-w-12))+'px';panel.style.top=Math.max(12,Math.min(r.bottom+8,innerHeight-Math.min(panel.scrollHeight,innerHeight-32)-12))+'px'}
function enhanceSelect(select){if(select.id==='ps-hero-date')return;select.classList.add('ps-native-select');select.tabIndex=-1;select.setAttribute('aria-hidden','true');let button=select.nextElementSibling;if(!button?.classList.contains('ps-select-button')){button=document.createElement('button');button.type='button';button.className='ps-select-button';button.setAttribute('role','combobox');button.setAttribute('aria-haspopup','listbox');button.dataset.selectId=select.id;select.after(button);button.addEventListener('click',()=>{if(openPopup&&popupAnchor===button){closePopup();return}const panel=document.createElement('div');panel.className='ps-select-panel';const label=root.querySelector('label[for="'+select.id+'"]')?.textContent||'Поиск по списку';if(select.options.length>8){const input=document.createElement('input');input.type='search';input.placeholder='Найти в списке';input.setAttribute('aria-label',label);panel.appendChild(input);input.addEventListener('input',()=>{for(const b of panel.querySelectorAll('[role=option]'))b.hidden=!b.textContent.toLowerCase().replace(/ё/g,'е').includes(input.value.toLowerCase().replace(/ё/g,'е'))})}const list=document.createElement('div');list.className='ps-select-options';list.setAttribute('role','listbox');for(const option of select.options){const b=document.createElement('button');b.type='button';b.setAttribute('role','option');b.setAttribute('aria-selected',String(option.value===select.value));b.disabled=option.disabled;b.textContent=option.textContent;b.addEventListener('click',()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));button.textContent=option.textContent;closePopup();button.focus()});list.appendChild(b)}panel.appendChild(list);placePopup(panel,button);(panel.querySelector('input')||panel.querySelector('[aria-selected=true]'))?.focus()})}button.textContent=select.selectedOptions[0]?.textContent||'Выберите';button.disabled=select.disabled;button.setAttribute('aria-label',(root.querySelector('label[for="'+select.id+'"]')?.textContent||'Выбрать')+': '+button.textContent);}
function enhanceSelects(){for(const s of root.querySelectorAll('select'))enhanceSelect(s)}
function dateButtonText(){if(state.rangeFrom)return isoLabel(state.rangeFrom)+(state.rangeTo&&state.rangeTo!==state.rangeFrom?' — '+isoLabel(state.rangeTo):'');if(state.date==='today')return'Сегодня';if(state.date==='tomorrow')return'Завтра';if(state.date==='weekend')return'Ближайшие выходные';return'Выбрать даты'}
function openCalendar(anchor){if(openPopup&&popupAnchor===anchor){closePopup();return}let from=state.rangeFrom,to=state.rangeTo,month=new Date((from||todayISO)+'T12:00:00');month.setDate(1);const panel=document.createElement('div');panel.className='ps-calendar';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Выбор даты или диапазона');function paint(){const months=innerWidth<650?1:2;let html='<div class="ps-calendar-head"><strong>Когда пойдём?</strong><button type="button" data-cal-close aria-label="Закрыть календарь">×</button></div><div class="ps-cal-quick">'+[['today','Сегодня'],['tomorrow','Завтра'],['weekend','Выходные'],['all','Все даты']].map(([k,t])=>`<button type="button" data-cal-quick="${k}">${t}</button>`).join('')+'</div><div class="ps-cal-months">';for(let m=0;m<months;m++){const d=new Date(month);d.setMonth(month.getMonth()+m);const y=d.getFullYear(),mo=d.getMonth(),days=new Date(y,mo+1,0).getDate(),offset=(d.getDay()+6)%7;html+=`<section><div class="ps-month-title">${m===0?'<button type="button" data-month="-1" aria-label="Предыдущий месяц">‹</button>':'<span></span>'}<b>${d.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</b>${m===months-1?'<button type="button" data-month="1" aria-label="Следующий месяц">›</button>':'<span></span>'}</div><div class="ps-cal-grid">`+['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(w=>`<small>${w}</small>`).join('')+'<span></span>'.repeat(offset);for(let day=1;day<=days;day++){const iso=y+'-'+String(mo+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');const count=items.filter(e=>(!state.types.length||state.types.some(t=>(e.categories||[e.type]).includes(t)))&&e.dates.some(p=>p.date===iso)).length;html+=`<button type="button" data-cal-date="${iso}" aria-label="${isoLabel(iso)}${count?', '+count+' событий':''}" ${iso<todayISO?'disabled':''} class="${iso===from||iso===to?'selected ':''}${from&&to&&iso>from&&iso<to?'between ':''}${count?'has-events':''}" aria-pressed="${iso===from||iso===to}">${day}</button>`}html+='</div></section>'}html+=`</div><div class="ps-cal-bottom"><span>${from?isoLabel(from)+(to?' — '+isoLabel(to):' · можно выбрать вторую дату'):'Выберите день или диапазон'}<small>Точки — опубликованные сеансы</small></span><button type="button" class="ps-main-button" data-cal-apply ${from?'':'disabled'}>Показать события</button></div>`;panel.innerHTML=html;panel.querySelector('[data-cal-close]').onclick=closePopup;for(const b of panel.querySelectorAll('[data-month]'))b.onclick=()=>{month.setMonth(month.getMonth()+Number(b.dataset.month));paint()};for(const b of panel.querySelectorAll('[data-cal-date]'))b.onclick=()=>{const date=b.dataset.calDate;if(!from||to){from=date;to=null}else if(date<from){to=from;from=date}else to=date;paint()};for(const b of panel.querySelectorAll('[data-cal-quick]'))b.onclick=()=>{state.date=b.dataset.calQuick;state.rangeFrom=null;state.rangeTo=null;state.catalogPage=0;closePopup();render();syncDateButtons()};panel.querySelector('[data-cal-apply]').onclick=()=>{state.rangeFrom=from;state.rangeTo=to||from;state.date='custom';state.catalogPage=0;closePopup();render();syncDateButtons()}}paint();placePopup(panel,anchor)}
function syncDateButtons(){for(const b of root.querySelectorAll('[data-calendar-open]'))b.textContent=dateButtonText();const s=$('#ps-hero-date');if(!s.querySelector('option[value=custom]'))s.add(new Option('Выбранные даты','custom'));s.value=state.date;}
const heroDate=$('#ps-hero-date');heroDate.classList.add('ps-native-select');heroDate.tabIndex=-1;heroDate.setAttribute('aria-hidden','true');const heroCalendar=document.createElement('button');heroCalendar.type='button';heroCalendar.className='ps-select-button ps-calendar-trigger';heroCalendar.dataset.calendarOpen='hero';heroCalendar.setAttribute('aria-haspopup','dialog');heroCalendar.addEventListener('click',()=>openCalendar(heroCalendar));heroDate.after(heroCalendar);
const datePills=$('.ps-date-pills');const calendarButton=document.createElement('button');calendarButton.type='button';calendarButton.className='ps-pill ps-calendar-trigger';calendarButton.dataset.calendarOpen='catalog';calendarButton.setAttribute('aria-haspopup','dialog');calendarButton.addEventListener('click',()=>openCalendar(calendarButton));datePills.appendChild(calendarButton);
const mapButton=document.createElement('button');mapButton.className='ps-icon-button';mapButton.type='button';mapButton.dataset.layout='map';mapButton.title='События на карте';mapButton.setAttribute('aria-label','Показать на карте');mapButton.innerHTML=icon('map');$('[data-layout="list"]').parentElement.appendChild(mapButton);
const advanced=$('.ps-advanced-location');advanced.innerHTML='<summary>Рядом со мной</summary><div class="ps-near-actions"><button type="button" class="ps-secondary" id="ps-use-location">Моё местоположение</button><button type="button" class="ps-text-button" id="ps-pick-location">Выбрать площадку на карте</button><p id="ps-near-label" class="ps-location-hint"></p></div><label for="ps-near-radius">Радиус от выбранной точки</label><select id="ps-near-radius"><option value="1">1 км</option><option value="3" selected>3 км</option><option value="5">5 км</option><option value="10">10 км</option></select><label for="ps-okrug">Административный округ</label><select id="ps-okrug"><option value="all">Все округа</option></select><label for="ps-district">Район</label><select id="ps-district"><option value="all">Все районы</option></select><label for="ps-metro">Метро, МЦК и МЦД</label><select id="ps-metro"><option value="all">Любая станция</option></select><label for="ps-metro-radius">Расстояние от станции</label><select id="ps-metro-radius"><option value="0.8">До 800 м</option><option value="1.5" selected>До 1,5 км</option><option value="3">До 3 км</option></select><label for="ps-venue">Площадка</label><select id="ps-venue"><option value="all">Любая площадка</option></select>';
