function renderContext(a){const cat=state.types.length===1?state.types[0]:null;const title=cat?categoryHeadings[cat]:'Куда сходить с ребёнком в Москве';$('#ps-catalog-heading').textContent=title;const relevant=cat?items.filter(e=>(e.categories||[e.type]).includes(cat)):items;let block=$('#ps-selection-content');if(!block){block=document.createElement('section');block.id='ps-selection-content';block.className='ps-selection-content';$('#ps-discovery-links').parentElement.after(block)}const copy=cat?categoryCopy[cat]:['Как выбрать мероприятие для ребёнка в Москве','Начните с интереса ребёнка: спектакли и концерты, мастер-классы, музейные программы, экскурсии или активные игры. Затем выберите дату, возраст и удобное место. Для поездки по Москве сравните адрес, расстояние до станции и время в пути.','Как пользоваться подборкой?','Выберите категорию и даты, затем уточните район, округ или станцию. При необходимости включите карту и задайте точку, от которой искать события.'];const prices=a.map(e=>e.price).filter(p=>p!=null&&p>0),free=a.filter(e=>e.priceData.free_confirmed).length;const venues=[...new Set(a.map(e=>e.place))];const context=[];if(state.age!=='all')context.push('Возрастной фильтр: '+state.age.replace('-','–')+' лет');if(state.free)context.push('Только бесплатные');if(state.venue!=='all')context.push('Площадка: '+state.venue);if(state.rangeFrom)context.push('Даты: '+dateButtonText());if(state.okrug!=='all')context.push('Округ: '+(geography.okrugs.find(o=>o.id===state.okrug)?.name||state.okrug));if(state.district!=='all')context.push('Район: '+state.district);if(state.metro!=='all')context.push('У станции '+geography.stations.find(s=>s.id===state.metro)?.name);if(nearPoint)context.push('В радиусе '+state.nearRadius+' км от выбранной точки');block.innerHTML=`<h2>${esc(copy[0])}</h2><p>${esc(copy[1])}</p><p>${context.length?esc(context.join(' · '))+'. ':''}${a.length?`В текущей подборке — ${number(a.length)} ${plural(a.length,'событие','события','событий')} на ${venues.length} площадках. Стоимость и условия опубликованы в карточках.${free?' Бесплатных программ — '+free+'.':''}`:'По выбранным условиям точные события пока не найдены. Можно изменить даты или место; категория и её адрес сохраняются.'}</p>${venues.length?'<h3>Площадки этой подборки</h3><p>'+venues.slice(0,5).map(esc).join(' · ')+'</p>':''}<h3>${esc(copy[2])}</h3><p>${esc(copy[3])}</p><h3>Где проверить даты, цены и наличие мест?</h3><p>В каждой карточке есть ссылка на исходную афишу. Расписание, свободные места и условия детских билетов уточняйте у площадки перед посещением.</p>`;const desc=cat?`${title}: ${relevant.length} событий, даты, цены, возрастные ограничения, площадки и карта. Выберите, на какой ${cat==='Концерты'?'концерт':'событие'} сходить с ребёнком.`:`Детская афиша Москвы: ${items.length} мероприятий. Спектакли, концерты, мастер-классы, музеи и экскурсии. Даты, цены, возраст и карта площадок.`;document.title=title+' — афиша и билеты | ProSchools';let meta=document.querySelector('meta[name=description]');if(!meta){meta=document.createElement('meta');meta.name='description';document.head.appendChild(meta)}meta.content=desc;const path='/afisha/moskva/'+(cat?categorySlugs[cat]+'/':'');let canonical=document.querySelector('link[rel=canonical]');if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.appendChild(canonical)}canonical.href='https://pro-schools.ru'+path;if(state.page==='catalog'&&location.protocol!=='file:'){const params=new URLSearchParams();if(!cat)params.set('view','catalog');if(state.rangeFrom){params.set('from',state.rangeFrom);params.set('to',state.rangeTo||state.rangeFrom)}else if(state.date!=='all')params.set('date',state.date);if(state.metro!=='all')params.set('metro',state.metro);if(state.district!=='all')params.set('rayon',state.district);if(state.okrug!=='all')params.set('okrug',state.okrug);if(state.age!=='all')params.set('age',state.age);if(state.venue!=='all')params.set('venue',state.venue);if(state.metro!=='all'&&state.metroRadius!==1.5)params.set('metro_radius',String(state.metroRadius));if(state.free)params.set('free','1');if(state.query)params.set('q',state.query);if(state.types.length>1)params.set('types',state.types.join(','));const url=path+(params.size?'?'+params.toString():'');if(location.pathname+location.search!==url){history.pushState(null,'',url)}}}
const oldDiscovery=renderDiscovery;renderDiscovery=function(){oldDiscovery();for(const a of $('#ps-discovery-links').querySelectorAll('[data-category]'))a.href='/afisha/moskva/'+categorySlugs[a.dataset.category]+'/'};
const originalCatalog=renderCatalog;renderCatalog=function(){originalCatalog();const a=filtered();$('#ps-catalog-grid').hidden=state.layout==='map';$('#ps-live-pagination').hidden=state.layout==='map';renderMap(a);renderContext(a);renderAlternatives(a);enhanceSelects();syncDateButtons();};
const originalHome=renderHome;renderHome=function(){originalHome();const subtitle=$('#ps-home-events').previousElementSibling?.querySelector('p');if(subtitle)subtitle.textContent='Москва · '+(state.rangeFrom||state.date!=='all'?dateButtonText():'Все даты');if(state.rangeFrom||state.date!=='all'){$('#ps-home-events').innerHTML=filtered().slice(0,6).map(card).join('')||'<p>На эти даты события пока не найдены. Выберите другой период.</p>'}syncDateButtons()};
root.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.date){state.rangeFrom=null;state.rangeTo=null}if(b.dataset.category){e.preventDefault();e.stopImmediatePropagation();state.types=[b.dataset.category];state.catalogPage=0;go('catalog')}if(b.dataset.remove==='dates'){e.preventDefault();e.stopImmediatePropagation();state.rangeFrom=null;state.rangeTo=null;state.date='all';state.catalogPage=0;render();}},true);
document.addEventListener('pointerdown',e=>{if(openPopup&&!openPopup.contains(e.target)&&!popupAnchor?.contains(e.target))closePopup()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&openPopup){const b=popupAnchor;closePopup();b?.focus()}});window.addEventListener('resize',closePopup);
function readRoute(){const params=new URLSearchParams(location.search);const cat=Object.keys(categorySlugs).find(c=>location.pathname.split('/').includes(categorySlugs[c]));state.types=cat?[cat]:(params.get('types')||'').split(',').filter(c=>categorySlugs[c]);state.rangeFrom=params.get('from');state.rangeTo=params.get('to')||state.rangeFrom;state.date=state.rangeFrom?'custom':params.get('date')||'all';state.metro=params.get('metro')||'all';state.district=params.get('rayon')||'all';state.okrug=params.get('okrug')||'all';state.age=['7-9','10-12','13-17'].includes(params.get('age'))?params.get('age'):'all';state.venue=params.get('venue')||'all';state.metroRadius=[0.8,1.5,3].includes(Number(params.get('metro_radius')))?Number(params.get('metro_radius')):1.5;state.free=params.get('free')==='1';state.query=params.get('q')||'';}
readRoute();
window.addEventListener('popstate',()=>{readRoute();state.page='catalog';state.catalogPage=0;render()});

function renderAlternatives(exact){let area=$('#ps-alternatives');if(!area){area=document.createElement('section');area.id='ps-alternatives';area.className='ps-alternatives';$('#ps-live-pagination').after(area)}area.hidden=exact.length>=6||state.favorites;if(area.hidden)return;let candidates=[],relaxed=false;const saved={date:state.date,rangeFrom:state.rangeFrom,rangeTo:state.rangeTo};try{Object.assign(state,{date:'all',rangeFrom:null,rangeTo:null});candidates=filtered().filter(e=>!exact.some(x=>x.id===e.id))}finally{Object.assign(state,saved)}if(!candidates.length){relaxed=true;candidates=items.filter(e=>(!state.types.length||state.types.some(t=>(e.categories||[e.type]).includes(t)))&&!exact.some(x=>x.id===e.id))}area.hidden=!candidates.length;if(area.hidden)return;const heading=relaxed?'Ещё варианты в этой категории':(state.rangeFrom||state.date!=='all'?'На другие даты и по записи':'Ещё варианты этой категории');area.innerHTML=`<div class="ps-alternatives-intro"><h2>${esc(heading)}</h2><p>${relaxed?'Эти события не совпадают со всеми выбранными условиями. Проверьте дату, возраст и место в карточке.':'Эти программы не подтверждены на выбранные даты. Их расписание и условия записи указаны в карточках.'}</p>${state.rangeFrom||state.date!=='all'?'<button type="button" class="ps-secondary" data-remove="dates">Показать все даты этой категории</button>':''}</div><div class="ps-card-grid">${candidates.slice(0,12).map(card).join('')}</div>`;if(!exact.length){$('#ps-empty').hidden=true;$('#ps-results-count').textContent='Точных совпадений пока нет · ниже другие варианты';}}

function selectedDateRange(){if(state.rangeFrom)return[state.rangeFrom,state.rangeTo||state.rangeFrom];if(state.date==='today')return[todayISO,todayISO];if(state.date==='tomorrow'){const d=addDay(todayISO,1);return[d,d]}if(state.date==='weekend'){const day=new Date(todayISO+'T12:00:00').getDay();const d=addDay(todayISO,(6-day+7)%7);return[d,addDay(d,1)]}return[null,null]}

